INSERT INTO public.questoes (id, disciplina_id, assunto_id, banca_id, orgao_id, cargo_id, prova_id, ano, tipo, dificuldade, enunciado, texto_apoio, explicacao, is_autoral_ia, modelo_ia, prompt_versao, revisada_por_especialista, anulada, desatualizada, fingerprint_hash) VALUES
('q-direito-previdenciario-segurados-rgps-1201', 'disc-direito-previdenciario', 'ass-segurados-rgps', 'banca-fgv', 'orgao-receita-federal', 'cargo-analista-adm', 'prova-rfb-2023-auditor', 2021, 'multipla_escolha', 'facil', 'Nos termos da Lei nº 8.213/1991, o indivíduo que presta serviço de natureza urbana ou rural à empresa, em caráter não eventual, sob sua subordinação e mediante remuneração, enquadra-se no RGPS como:', NULL, 'Lei nº 8.213/1991, art. 11, I, ''a'': É segurado obrigatório da Previdência Social como empregado quem presta serviço de natureza urbana ou rural à empresa, em caráter não eventual, sob sua subordinação e mediante remuneração.', true, 'claude-3-5-sonnet', 'v2.1', true, false, false, 'f0f5b41a82560973fd12ad5d69dc26f15a0c16d99dcb1212938d99f90dbf718e'),
