INSERT INTO public.questoes_alternativas (id, questao_id, letra, texto, correta, ordem, explicacao_especifica) VALUES
('alt-q-portugues-sintaxe-001-A', 'q-portugues-sintaxe-001', 'A', 'Oração Subordinada Adverbial Concessiva.', true, 1, 'Correto. ''Embora'' é conjunção subordinativa concessiva por excelência.'),
('alt-q-portugues-sintaxe-001-B', 'q-portugues-sintaxe-001', 'B', 'Oração Subordinada Adverbial Causal.', false, 2, 'Incorreto. A causalidade é expressa por conectivos como ''porque'', ''visto que'', ''já que''.'),
('alt-q-portugues-sintaxe-001-C', 'q-portugues-sintaxe-001', 'C', 'Oração Subordinada Adverbial Consecutiva.', false, 3, 'Incorreto. A consecutiva expressa consequência (''tanto... que'').'),
('alt-q-portugues-sintaxe-001-D', 'q-portugues-sintaxe-001', 'D', 'Oração Coordenada Adversativa.', false, 4, 'Incorreto. As adversativas pertencem à coordenação (''mas'', ''porém'', ''contudo'').'),
('alt-q-portugues-sintaxe-001-E', 'q-portugues-sintaxe-001', 'E', 'Oração Subordinada Adverbial Proporcional.', false, 5, 'Incorreto. A proporcionalidade exige ''à medida que'', ''à proporção que''.'),
('alt-q-portugues-sintaxe-002-A', 'q-portugues-sintaxe-002', 'A', '''ao corregedor-geral'' atua como Objeto Indireto.', true, 1, 'Correto. Completa o sentido do VTDI com preposição obrigatória.'),
('alt-q-portugues-sintaxe-002-B', 'q-portugues-sintaxe-002', 'B', '''o relatório conclusivo'' atua como Sujeito Simples.', false, 2, 'Incorreto. ''O auditor'' é o sujeito simples; ''o relatório conclusivo'' é objeto direto.'),
('alt-q-portugues-sintaxe-002-C', 'q-portugues-sintaxe-002', 'C', '''ao corregedor-geral'' atua como Complemento Nominal.', false, 3, 'Incorreto. Completa verbo transitivo, sendo portanto objeto indireto.'),
('alt-q-portugues-sintaxe-002-D', 'q-portugues-sintaxe-002', 'D', '''conclusivo'' atua como Predicativo do Sujeito.', false, 4, 'Incorreto. É adjunto adnominal do substantivo ''relatório''.'),
('alt-q-portugues-sintaxe-002-E', 'q-portugues-sintaxe-002', 'E', '''O auditor'' atua como Vocativo.', false, 5, 'Incorreto. É o sujeito agente da oração.'),
('alt-q-portugues-sintaxe-003-A', 'q-portugues-sintaxe-003', 'A', 'Sujeito (Oração Subordinada Substantiva Subjetiva).', true, 1, 'Correto. Equivale a: ''Isto foi constatado''.'),
('alt-q-portugues-sintaxe-003-B', 'q-portugues-sintaxe-003', 'B', 'Objeto Direto (Oração Subordinada Substantiva Objetiva Direta).', false, 2, 'Incorreto. Com ''se'' apassivador, não há objeto direto, mas sim sujeito.'),
('alt-q-portugues-sintaxe-003-C', 'q-portugues-sintaxe-003', 'C', 'Complemento Nominal.', false, 3, 'Incorreto. Completa sentido verbal, exercendo função de sujeito.'),
('alt-q-portugues-sintaxe-003-D', 'q-portugues-sintaxe-003', 'D', 'Predicativo do Sujeito.', false, 4, 'Incorreto. O verbo ''constatar'' não é verbo de ligação.'),
('alt-q-portugues-sintaxe-003-E', 'q-portugues-sintaxe-003', 'E', 'Aposto Explicativo.', false, 5, 'Incorreto. Não está explicando termo nominal antecedente entre vírgulas.'),
('alt-q-portugues-sintaxe-004-C', 'q-portugues-sintaxe-004', 'C', 'Certo', true, 1, 'Correto. O verbo ''fazer'' temporal é impessoal e invariável no singular.'),
('alt-q-portugues-sintaxe-004-E', 'q-portugues-sintaxe-004', 'E', 'Errado', false, 2, 'Incorreto. O verbo é rigorosamente impessoal nessa acepção.'),
('alt-q-portugues-sintaxe-005-A', 'q-portugues-sintaxe-005', 'A', 'Posse, funcionando sintaticamente como adjunto adnominal.', true, 1, 'Correto. ''A elaboração do parecer técnico''.'),
('alt-q-portugues-sintaxe-005-B', 'q-portugues-sintaxe-005', 'B', 'Causa, funcionando sintaticamente como adjunto adverbial.', false, 2, 'Incorreto. ''Cuja'' nunca expressa causa.'),
('alt-q-portugues-sintaxe-005-C', 'q-portugues-sintaxe-005', 'C', 'Finalidade, funcionando como complemento nominal.', false, 3, 'Incorreto. Não exprime destinação ou objetivo.'),
('alt-q-portugues-sintaxe-005-D', 'q-portugues-sintaxe-005', 'D', 'Consequência, atuando como predicativo do objeto.', false, 4, 'Incorreto. ''Cujo'' é estritamente possessivo.'),
('alt-q-portugues-sintaxe-005-E', 'q-portugues-sintaxe-005', 'E', 'Explicação coordenada, sem valor anafórico.', false, 5, 'Incorreto. É pronome relativo e, portanto, anafórico por excelência.'),
('alt-q-portugues-concordancia-001-A', 'q-portugues-concordancia-001', 'A', 'Havia muitas dúvidas entre os candidatos sobre os critérios de desempate do edital.', true, 1, 'Correto. O verbo ''haver'' no sentido de existir é impessoal e fica na 3ª pessoa do singular.'),
('alt-q-portugues-concordancia-001-B', 'q-portugues-concordancia-001', 'B', 'Haviam muitas dúvidas entre os candidatos sobre os critérios de desempate do edital.', false, 2, 'Incorreto. ''Haver'' existencial não vai para o plural.'),
('alt-q-portugues-concordancia-001-C', 'q-portugues-concordancia-001', 'C', 'Fazem três meses que a comissão organizadora não publica retificações.', false, 3, 'Incorreto. ''Fazer'' indicando tempo é impessoal (deve ser ''Faz três meses'').'),
('alt-q-portugues-concordancia-001-D', 'q-portugues-concordancia-001', 'D', 'Devem haver alternativas mais eficientes para otimizar os recursos do tribunal.', false, 4, 'Incorreto. Em locução com ''haver'' impessoal, o verbo auxiliar também fica no singular (''Deve haver'').'),
('alt-q-portugues-concordancia-001-E', 'q-portugues-concordancia-001', 'E', 'Tratam-se de processos administrativos de alta complexidade orçamentária.', false, 5, 'Incorreto. Com verbo transitivo indireto + ''se'' (índice de indeterminação), o verbo fica no singular: ''Trata-se de''.'),
('alt-q-portugues-concordancia-002-A', 'q-portugues-concordancia-002', 'A', 'As testemunhas pareciam meio preocupadas com os desdobramentos do depoimento prestado.', true, 1, 'Correto. ''Meio'' é advérbio de intensidade e permanece invariável.'),
('alt-q-portugues-concordancia-002-B', 'q-portugues-concordancia-002', 'B', 'As testemunhas pareciam meias preocupadas com os desdobramentos do depoimento prestado.', false, 2, 'Incorreto. ''Meia'' como advérbio não existe na norma culta.'),
('alt-q-portugues-concordancia-002-C', 'q-portugues-concordancia-002', 'C', 'Seguem anexo as certidões negativas solicitadas pela corregedoria.', false, 3, 'Incorreto. ''Anexo'' como adjetivo concorda em gênero e número (''Seguem anexas as certidões'').'),
('alt-q-portugues-concordancia-002-D', 'q-portugues-concordancia-002', 'D', 'É proibido a divulgação de dados sigilosos sem autorização judicial.', false, 4, 'Incorreto. A presença do artigo ''a'' exige concordância: ''É proibida a divulgação''.'),
('alt-q-portugues-concordancia-002-E', 'q-portugues-concordancia-002', 'E', 'Havia bastantes pessoas meia nervosas durante a audiência de instrução.', false, 5, 'Incorreto. ''Meia'' advérbio está incorreto (deve ser ''meio nervosas'').'),
('alt-q-portugues-concordancia-003-C', 'q-portugues-concordancia-003', 'C', 'Certo', true, 1, 'Correto. ''Mais de um'' exige verbo no singular concordando com ''um''.'),
('alt-q-portugues-concordancia-003-E', 'q-portugues-concordancia-003', 'E', 'Errado', false, 2, 'Incorreto. A concordância no singular é a regra canônica.'),
('alt-q-portugues-concordancia-004-A', 'q-portugues-concordancia-004', 'A', 'Existe, nos arquivos do departamento, várias pendências documentais não sanadas.', true, 1, 'Correto (apresenta erro). O verbo ''existir'' tem sujeito (''várias pendências'') e deveria estar no plural: ''Existem''.'),
('alt-q-portugues-concordancia-004-B', 'q-portugues-concordancia-004', 'B', 'Devem existir razões plausíveis para o cancelamento sumário do certame.', false, 2, 'Incorreto (está correta). ''Existir'' transmite a pessoalidade para o auxiliar ''devem''.'),
('alt-q-portugues-concordancia-004-C', 'q-portugues-concordancia-004', 'C', 'Fazem-se necessárias intervenções urgentes na gestão de tecnologia.', false, 3, 'Incorreto (está correta). Voz passiva sintética: ''intervenções'' é sujeito plural.'),
('alt-q-portugues-concordancia-004-D', 'q-portugues-concordancia-004', 'D', 'Mais de vinte servidores foram homenageados pela dedicação ao serviço público.', false, 4, 'Incorreto (está correta). ''Mais de vinte'' concorda com o numeral ''vinte'' no plural.'),
('alt-q-portugues-concordancia-004-E', 'q-portugues-concordancia-004', 'E', 'Nenhum dos conselheiros manifestou discordância quanto à ata da reunião anterior.', false, 5, 'Incorreto (está correta). ''Nenhum dos'' admite concordância com o pronome no singular.'),
('alt-q-portugues-regencia-crase-001-A', 'q-portugues-regencia-crase-001', 'A', 'À medida que os prazos processuais transcorriam, a tensão entre as partes aumentava.', true, 1, 'Correto. Locução conjuntiva feminina exige crase obrigatória.'),
('alt-q-portugues-regencia-crase-001-B', 'q-portugues-regencia-crase-001', 'B', 'As novas diretrizes orçamentárias entrarão em vigor à partir do próximo semestre.', false, 2, 'Incorreto. Não ocorre crase antes de verbo (''partir'').'),
('alt-q-portugues-regencia-crase-001-C', 'q-portugues-regencia-crase-001', 'C', 'O diretor prestou esclarecimentos à todas as chefias de departamento reunidas.', false, 3, 'Incorreto. Não há artigo antes de pronome indefinido ''todas''.'),
('alt-q-portugues-regencia-crase-001-D', 'q-portugues-regencia-crase-001', 'D', 'A comissão dirigiu-se à ela com urbanidade e estrita observância legal.', false, 4, 'Incorreto. Não ocorre crase antes de pronome pessoal do caso reto (''ela'').'),
('alt-q-portugues-regencia-crase-001-E', 'q-portugues-regencia-crase-001', 'E', 'O órgão efetuou a aquisição de equipamentos de informática à prazo.', false, 5, 'Incorreto. Não ocorre crase antes de palavra masculina (''prazo'').'),
('alt-q-portugues-regencia-crase-002-A', 'q-portugues-regencia-crase-002', 'A', 'O servidor aspirava ao cargo de direção com determinação e preparo técnico.', true, 1, 'Correto. ''Aspirar'' = almejar é VTI com preposição ''a''.'),
('alt-q-portugues-regencia-crase-002-B', 'q-portugues-regencia-crase-002', 'B', 'O servidor aspirava o cargo de direção com determinação e preparo técnico.', false, 2, 'Incorreto. ''Aspirar o'' significaria inalar fisicamente o cargo.'),
('alt-q-portugues-regencia-crase-002-C', 'q-portugues-regencia-crase-002', 'C', 'O relatório visa um aprimoramento substancial dos controles internos do órgão.', false, 3, 'Incorreto. ''Visar'' = ter por objetivo é VTI (''visa a um aprimoramento'').'),
('alt-q-portugues-regencia-crase-002-D', 'q-portugues-regencia-crase-002', 'D', 'O advogado assistiu o cliente durante todo o depoimento na polícia federal.', false, 4, 'Incorreto. Embora ''assistir'' = ajudar admita VTD/VTI, no sentido de presenciar/ver é VTI com ''a''.'),
('alt-q-portugues-regencia-crase-002-E', 'q-portugues-regencia-crase-002', 'E', 'Ele preferia mais trabalhar remotamente do que comparecer à repartição física.', false, 5, 'Incorreto. ''Preferir'' não admite intensificador (''mais'') nem a correlação ''do que'' (exige: ''preferia X a Y'').'),
('alt-q-portugues-regencia-crase-003-C', 'q-portugues-regencia-crase-003', 'C', 'Certo', false, 1, 'Incorreto. A segunda crase constitui erro de regência verbal.'),
('alt-q-portugues-regencia-crase-003-E', 'q-portugues-regencia-crase-003', 'E', 'Errado', true, 2, 'Correto. A segunda ocorrência de crase é indevida (''vincula a administração'').'),
('alt-q-portugues-interpretacao-001-A', 'q-portugues-interpretacao-001', 'A', 'Fortalecer a tese principal ao antecipar e neutralizar eventuais objeções lógicas.', true, 1, 'Correto. Essa estratégia argumentativa consolida a credibilidade da tese.'),
('alt-q-portugues-interpretacao-001-B', 'q-portugues-interpretacao-001', 'B', 'Demonstrar indecisão do autor frente à controvérsia analisada.', false, 2, 'Incorreto. Não expressa dúvida, mas sim domínio do debate.'),
('alt-q-portugues-interpretacao-001-C', 'q-portugues-interpretacao-001', 'C', 'Tornar o texto narrativo ao inserir personagens com pontos de vista antagônicos.', false, 3, 'Incorreto. O texto permanece dissertativo-argumentativo.'),
('alt-q-portugues-interpretacao-001-D', 'q-portugues-interpretacao-001', 'D', 'Anular integralmente a validade de qualquer dado estatístico citado previamente.', false, 4, 'Incorreto. Não tem relação direta com invalidação de estatísticas.'),
('alt-q-portugues-interpretacao-001-E', 'q-portugues-interpretacao-001', 'E', 'Restringir o alcance da conclusão a uma esfera puramente hipotética.', false, 5, 'Incorreto. A conclusão visa persuadir sobre a tese principal.'),
('alt-q-portugues-interpretacao-002-A', 'q-portugues-interpretacao-002', 'A', 'Metonímia (continente pelo conteúdo / instituição pelos seus membros).', true, 1, 'Correto. ''O plenário julgou'' substitui ''os ministros julgaram''.'),
('alt-q-portugues-interpretacao-002-B', 'q-portugues-interpretacao-002', 'B', 'Hipérbole (exagero intencional de uma expressão).', false, 2, 'Incorreto. Não há ampliação desmedida ou inverossímil.'),
('alt-q-portugues-interpretacao-002-C', 'q-portugues-interpretacao-002', 'C', 'Prosopopeia (atribuição de características animadas a seres inanimados com fins poéticos).', false, 3, 'Incorreto. É metonímia institucional formal.'),
('alt-q-portugues-interpretacao-002-D', 'q-portugues-interpretacao-002', 'D', 'Eufemismo (suavização de uma ideia desagradável).', false, 4, 'Incorreto. Não há abrandamento de fato trágico ou ofensivo.'),
('alt-q-portugues-interpretacao-002-E', 'q-portugues-interpretacao-002', 'E', 'Antítese (aproximação de ideias ou termos semanticamente opostos).', false, 5, 'Incorreto. Não há contraste ou oposição conceitual.'),
('alt-q-portugues-pontuacao-001-A', 'q-portugues-pontuacao-001', 'A', 'Os servidores recém-empossados no cargo, apresentaram todos os diplomas exigidos no edital.', true, 1, 'Correto (apresenta erro). Vírgula proibida entre sujeito (''Os servidores...'') e verbo (''apresentaram'').'),
('alt-q-portugues-pontuacao-001-B', 'q-portugues-pontuacao-001', 'B', 'Durante a realização da prova, nenhum candidato pôde utilizar aparelhos eletrônicos.', false, 2, 'Incorreto (está correta). Adjunto adverbial deslocado isolado por vírgula.'),
('alt-q-portugues-pontuacao-001-C', 'q-portugues-pontuacao-001', 'C', 'Brasília, 24 de setembro de 2024.', false, 3, 'Incorreto (está correta). Vírgula obrigatória para separar localidade de data.'),
('alt-q-portugues-pontuacao-001-D', 'q-portugues-pontuacao-001', 'D', 'O diretor executivo, homem de conduta ilibada, presidiu a comissão de ética.', false, 4, 'Incorreto (está correta). Aposto explicativo isolado por vírgulas.'),
('alt-q-portugues-pontuacao-001-E', 'q-portugues-pontuacao-001', 'E', 'Estudou com afinco e disciplina, porém não alcançou a pontuação mínima na prova discursiva.', false, 5, 'Incorreto (está correta). Vírgula antes de conjunção adversativa.'),
('alt-q-portugues-pontuacao-002-C', 'q-portugues-pontuacao-002', 'C', 'Certo', true, 1, 'Correto. Introduz enumeração detalhadora dos termos anunciados.'),
('alt-q-portugues-pontuacao-002-E', 'q-portugues-pontuacao-002', 'E', 'Errado', false, 2, 'Incorreto. O uso dos dois-pontos é canônico nesse contexto.'),
('alt-q-portugues-ortografia-acentuacao-001-A', 'q-portugues-ortografia-acentuacao-001', 'A', 'órgão / bênção', true, 1, 'Correto. Ambas são paroxítonas terminadas em ditongo nasal/til.'),
('alt-q-portugues-ortografia-acentuacao-001-B', 'q-portugues-ortografia-acentuacao-001', 'B', 'relatório / café', false, 2, 'Incorreto. ''Relatório'' é paroxítona terminada em ditongo crescente; ''café'' é oxítona terminada em ''e''.'),
('alt-q-portugues-ortografia-acentuacao-001-C', 'q-portugues-ortografia-acentuacao-001', 'C', 'juiz / juízes', false, 3, 'Incorreto. ''Juiz'' não tem acento (hiato com z); ''juízes'' é proparoxítona.'),
('alt-q-portugues-ortografia-acentuacao-001-D', 'q-portugues-ortografia-acentuacao-001', 'D', 'saúde / baú', false, 4, 'Incorreto. ''Saúde'' é paroxítona com hiato em ''ú''; ''baú'' é oxítona terminada em ''ú''.'),
('alt-q-portugues-ortografia-acentuacao-001-E', 'q-portugues-ortografia-acentuacao-001', 'E', 'público / país', false, 5, 'Incorreto. ''Público'' é proparoxítona; ''país'' é hiato tônico em ''i'' seguido de ''s''.'),
('alt-q-portugues-ortografia-acentuacao-002-A', 'q-portugues-ortografia-acentuacao-002', 'A', 'micro-ondas / autoestrada / anti-inflamatório', true, 1, 'Correto. Vogais iguais separam com hífen; vogais diferentes unem-se sem hífen.'),
('alt-q-portugues-ortografia-acentuacao-002-B', 'q-portugues-ortografia-acentuacao-002', 'B', 'microondas / auto-estrada / antiinflamatório', false, 2, 'Incorreto. ''Micro-ondas'' e ''anti-inflamatório'' exigem hífen; ''autoestrada'' não tem hífen.'),
('alt-q-portugues-ortografia-acentuacao-002-C', 'q-portugues-ortografia-acentuacao-002', 'C', 'contra-regra / auto-escola / super-homem', false, 3, 'Incorreto. ''Contrarregra'' dobra o ''r''; ''autoescola'' é junto sem hífen.'),
('alt-q-portugues-ortografia-acentuacao-002-D', 'q-portugues-ortografia-acentuacao-002', 'D', 'sub-reitor / infra-estrutura / hiper-mercado', false, 4, 'Incorreto. ''Infraestrutura'' é junto sem hífen; ''hipermercado'' é junto sem hífen.'),
('alt-q-portugues-ortografia-acentuacao-002-E', 'q-portugues-ortografia-acentuacao-002', 'E', 'anti-social / sobre-aviso / ex-diretor', false, 5, 'Incorreto. ''Antissocial'' dobra o ''s''; ''sobreaviso'' é junto sem hífen.'),
('alt-q-portugues-morfologia-classes-001-A', 'q-portugues-morfologia-classes-001', 'A', 'Pronome Indefinido (com valor adjetivo).', true, 1, 'Correto. Modifica o substantivo ''argumentos'', equivalendo a ''muitos''.'),
('alt-q-portugues-morfologia-classes-001-B', 'q-portugues-morfologia-classes-001', 'B', 'Advérbio de Intensidade.', false, 2, 'Incorreto. Advérbios são invariáveis e modificam verbos, adjetivos ou outros advérbios.'),
('alt-q-portugues-morfologia-classes-001-C', 'q-portugues-morfologia-classes-001', 'C', 'Adjetivo Explicativo.', false, 3, 'Incorreto. Não exprime qualidade inerente, mas sim quantidade indefinida.'),
('alt-q-portugues-morfologia-classes-001-D', 'q-portugues-morfologia-classes-001', 'D', 'Conjunção Subordinativa Integrante.', false, 4, 'Incorreto. Não conecta orações.'),
('alt-q-portugues-morfologia-classes-001-E', 'q-portugues-morfologia-classes-001', 'E', 'Substantivo Comum Concreto.', false, 5, 'Incorreto. Não nomeia ser ou entidade.'),
('alt-q-portugues-morfologia-classes-002-C', 'q-portugues-morfologia-classes-002', 'C', 'Certo', true, 1, 'Correto. Trata-se de adjetivo com valor de advérbio modal.'),
('alt-q-portugues-morfologia-classes-002-E', 'q-portugues-morfologia-classes-002', 'E', 'Errado', false, 2, 'Incorreto. O termo desempenha inquestionavelmente função adverbial.'),
('alt-q-direito-constitucional-direitos-fundamentais-001-A', 'q-direito-constitucional-direitos-fundamentais-001', 'A', 'Durante o dia, por determinação judicial, ou a qualquer hora em flagrante delito, desastre ou para prestar socorro.', true, 1, 'Correto. Literalidade do art. 5º, XI, da CF/88.'),
('alt-q-direito-constitucional-direitos-fundamentais-001-B', 'q-direito-constitucional-direitos-fundamentais-001', 'B', 'A qualquer hora do dia ou da noite por ordem fundamentada de autoridade policial.', false, 2, 'Incorreto. Exige determinação judicial e apenas durante o dia.'),
('alt-q-direito-constitucional-direitos-fundamentais-001-C', 'q-direito-constitucional-direitos-fundamentais-001', 'C', 'Durante a noite, por mandado judicial assinado por juiz federal competente.', false, 3, 'Incorreto. Cumprimento de mandado judicial só é lícito durante o dia.'),
('alt-q-direito-constitucional-direitos-fundamentais-001-D', 'q-direito-constitucional-direitos-fundamentais-001', 'D', 'Em caso de mera suspeita de crime punível com reclusão, a qualquer momento.', false, 4, 'Incorreto. Exige fundadas razões de flagrante delito (STF RE 603.616).'),
('alt-q-direito-constitucional-direitos-fundamentais-001-E', 'q-direito-constitucional-direitos-fundamentais-001', 'E', 'Exclusivamente mediante consentimento expresso do proprietário do imóvel.', false, 5, 'Incorreto. Há as exceções constitucionais expressas independentes de consentimento.'),
('alt-q-direito-constitucional-direitos-fundamentais-002-A', 'q-direito-constitucional-direitos-fundamentais-002', 'A', 'Habeas Data.', true, 1, 'Correto. Instrumento específico para acesso a dados personalíssimos (art. 5º, LXXII, CF).'),
('alt-q-direito-constitucional-direitos-fundamentais-002-B', 'q-direito-constitucional-direitos-fundamentais-002', 'B', 'Mandado de Segurança Individual.', false, 2, 'Incorreto. O MS é residual e não cabe para situações amparadas por habeas data ou habeas corpus.'),
('alt-q-direito-constitucional-direitos-fundamentais-002-C', 'q-direito-constitucional-direitos-fundamentais-002', 'C', 'Habeas Corpus.', false, 3, 'Incorreto. O HC tutela a liberdade de locomoção.'),
('alt-q-direito-constitucional-direitos-fundamentais-002-D', 'q-direito-constitucional-direitos-fundamentais-002', 'D', 'Mandado de Injunção.', false, 4, 'Incorreto. O MI combate a falta de norma regulamentadora que inviabilize direito constitucional.'),
('alt-q-direito-constitucional-direitos-fundamentais-002-E', 'q-direito-constitucional-direitos-fundamentais-002', 'E', 'Ação Popular.', false, 5, 'Incorreto. A AP visa anular ato lesivo ao patrimônio público, moralidade, meio ambiente ou patrimônio histórico.'),
('alt-q-direito-constitucional-direitos-fundamentais-003-C', 'q-direito-constitucional-direitos-fundamentais-003', 'C', 'Certo', false, 1, 'Incorreto. A CF garante expressamente a gratuidade de ambas as ações.'),
('alt-q-direito-constitucional-direitos-fundamentais-003-E', 'q-direito-constitucional-direitos-fundamentais-003', 'E', 'Errado', true, 2, 'Correto. HC e HD são ações constitucionais expressamente gratuitas.'),
('alt-q-direito-constitucional-direitos-fundamentais-004-A', 'q-direito-constitucional-direitos-fundamentais-004', 'A', 'O brasileiro nato jamais será extraditado pelo Brasil.', true, 1, 'Correto. Garantia absoluta do brasileiro nato (art. 5º, LI, CF).'),
('alt-q-direito-constitucional-direitos-fundamentais-004-B', 'q-direito-constitucional-direitos-fundamentais-004', 'B', 'O brasileiro nato pode ser extraditado caso cometa crime de genocídio no exterior.', false, 2, 'Incorreto. Não há exceção que autorize a extradição de brasileiro nato.'),
('alt-q-direito-constitucional-direitos-fundamentais-004-C', 'q-direito-constitucional-direitos-fundamentais-004', 'C', 'O estrangeiro pode ser extraditado por crime político ou de opinião.', false, 3, 'Incorreto. O art. 5º, LII, veda expressamente extradição por crime político ou de opinião.'),
('alt-q-direito-constitucional-direitos-fundamentais-004-D', 'q-direito-constitucional-direitos-fundamentais-004', 'D', 'O brasileiro naturalizado pode ser extraditado por qualquer crime comum a qualquer tempo.', false, 4, 'Incorreto. Crime comum apenas se praticado ANTES da naturalização.'),
('alt-q-direito-constitucional-direitos-fundamentais-004-E', 'q-direito-constitucional-direitos-fundamentais-004', 'E', 'A extradição de estrangeiro prescinde de autorização do Supremo Tribunal Federal.', false, 5, 'Incorreto. A competência para processar e julgar a extradição é privativa do STF (art. 102, I, ''g'').'),
('alt-q-direito-constitucional-organizacao-estado-001-A', 'q-direito-constitucional-organizacao-estado-001', 'A', 'Integra a União, sendo regulada por lei complementar federal.', true, 1, 'Correto. Literalidade do art. 18, § 2º, da CF/88.'),
('alt-q-direito-constitucional-organizacao-estado-001-B', 'q-direito-constitucional-organizacao-estado-001', 'B', 'Cria um novo ente federativo dotado de autonomia política plena.', false, 2, 'Incorreto. Territórios não possuem autonomia política própria.'),
('alt-q-direito-constitucional-organizacao-estado-001-C', 'q-direito-constitucional-organizacao-estado-001', 'C', 'Pode ser realizada por simples decreto do Presidente da República.', false, 3, 'Incorreto. Exige aprovação de Lei Complementar pelo Congresso Nacional.'),
('alt-q-direito-constitucional-organizacao-estado-001-D', 'q-direito-constitucional-organizacao-estado-001', 'D', 'Independe de consulta plebiscitária às populações interessadas.', false, 4, 'Incorreto. A consulta plebiscitária é obrigatória.'),
('alt-q-direito-constitucional-organizacao-estado-001-E', 'q-direito-constitucional-organizacao-estado-001', 'E', 'É vedada desde a promulgação da Emenda Constitucional nº 45/2004.', false, 5, 'Incorreto. A figura dos Territórios Federais continua plenamente prevista na CF.'),
('alt-q-direito-constitucional-organizacao-estado-002-C', 'q-direito-constitucional-organizacao-estado-002', 'C', 'Certo', true, 1, 'Correto. Literalidade do art. 22, I, da CF/88 (regrinha do CAPACETE de PM).'),
('alt-q-direito-constitucional-organizacao-estado-002-E', 'q-direito-constitucional-organizacao-estado-002', 'E', 'Errado', false, 2, 'Incorreto. A assertiva reflete exatamente o rol do art. 22, I.'),
('alt-q-direito-constitucional-poder-executivo-001-A', 'q-direito-constitucional-poder-executivo-001', 'A', 'Far-se-á eleição direta noventa dias depois de aberta a última vaga.', true, 1, 'Correto. Nos 2 primeiros anos a eleição é direta pelo povo em 90 dias (art. 81, caput).'),
('alt-q-direito-constitucional-poder-executivo-001-B', 'q-direito-constitucional-poder-executivo-001', 'B', 'O Congresso Nacional elegerá os substitutos em eleição indireta em trinta dias.', false, 2, 'Incorreto. A eleição indireta em 30 dias ocorre se a vacância se der nos últimos 2 anos (art. 81, § 1º).'),
('alt-q-direito-constitucional-poder-executivo-001-C', 'q-direito-constitucional-poder-executivo-001', 'C', 'O Presidente do Senado Federal assume em definitivo até o fim do mandato.', false, 3, 'Incorreto. A assunção dos presidentes das Casas Legislativas e STF é meramente interina.'),
('alt-q-direito-constitucional-poder-executivo-001-D', 'q-direito-constitucional-poder-executivo-001', 'D', 'O Presidente da Câmara dos Deputados governa com plenos poderes por dois anos.', false, 4, 'Incorreto. Exerce apenas a substituição temporária até a posse dos novos eleitos.'),
('alt-q-direito-constitucional-poder-executivo-001-E', 'q-direito-constitucional-poder-executivo-001', 'E', 'Decretar-se-á intervenção federal imediata em todos os Estados da Federação.', false, 5, 'Incorreto. Hipótese desprovida de qualquer fundamento constitucional.'),
('alt-q-direito-constitucional-poder-legislativo-001-A', 'q-direito-constitucional-poder-legislativo-001', 'A', 'A proposta de emenda deve ser discutida e votada em cada Casa do Congresso Nacional, em dois turnos, exigindo três quintos dos votos dos respectivos membros.', true, 1, 'Correto. Regra do quorum qualificado de 3/5 em 2 turnos nas 2 Casas (art. 60, § 2º).'),
('alt-q-direito-constitucional-poder-legislativo-001-B', 'q-direito-constitucional-poder-legislativo-001', 'B', 'A emenda aprovada é enviada ao Presidente da República para sanção ou veto.', false, 2, 'Incorreto. Emenda constitucional não se sujeita a sanção ou veto presidencial (é promulgada pelas Mesas da CD e SF).'),
('alt-q-direito-constitucional-poder-legislativo-001-C', 'q-direito-constitucional-poder-legislativo-001', 'C', 'Pode ser proposta por iniciativa popular subscrita por 1% do eleitorado nacional.', false, 3, 'Incorreto. A CF não prevê iniciativa popular direta para PEC, apenas para lei ordinária/complementar.'),
('alt-q-direito-constitucional-poder-legislativo-001-D', 'q-direito-constitucional-poder-legislativo-001', 'D', 'A Constituição pode ser emendada na vigência de estado de sítio ou estado de defesa.', false, 4, 'Incorreto. São limitações circunstanciais expressas (art. 60, § 1º).'),
('alt-q-direito-constitucional-poder-legislativo-001-E', 'q-direito-constitucional-poder-legislativo-001', 'E', 'A matéria constante de PEC rejeitada pode ser reapresentada na mesma sessão legislativa por maioria absoluta.', false, 5, 'Incorreto. Matéria de PEC rejeitada não pode ser reapresentada na mesma sessão (art. 60, § 5º).'),
('alt-q-direito-constitucional-poder-judiciario-001-A', 'q-direito-constitucional-poder-judiciario-001', 'A', 'Competência estritamente administrativa, financeira e disciplinar, sem função jurisdicional.', true, 1, 'Correto. O CNJ não julga ações judiciais, atuando no controle administrativo e disciplinar.'),
('alt-q-direito-constitucional-poder-judiciario-001-B', 'q-direito-constitucional-poder-judiciario-001', 'B', 'Poder para reformar decisões jurisdicionais transitadas em julgado do STF.', false, 2, 'Incorreto. O CNJ não tem poder jurisdicional e o STF é seu órgão revisor.'),
('alt-q-direito-constitucional-poder-judiciario-001-C', 'q-direito-constitucional-poder-judiciario-001', 'C', 'Sede itinerante em todas as capitais estaduais sem vinculação a Brasília.', false, 3, 'Incorreto. A sede do CNJ é em Brasília/DF.'),
('alt-q-direito-constitucional-poder-judiciario-001-D', 'q-direito-constitucional-poder-judiciario-001', 'D', 'Composição exclusiva de magistrados de carreira sem participação do Ministério Público ou OAB.', false, 4, 'Incorreto. Conta com membros do MP, advogados da OAB e cidadãos indicados pelo Congresso.'),
('alt-q-direito-constitucional-poder-judiciario-001-E', 'q-direito-constitucional-poder-judiciario-001', 'E', 'Competência para julgar o Presidente da República em crimes de responsabilidade.', false, 5, 'Incorreto. Competência privativa do Senado Federal (art. 52, I, CF).'),
('alt-q-direito-constitucional-controle-constitucionalidade-001-A', 'q-direito-constitucional-controle-constitucionalidade-001', 'A', 'Confederação Sindical ou Entidade de Classe de âmbito nacional (legitimado especial).', true, 1, 'Correto. Exige demonstração de pertinência temática com suas finalidades institucionais.'),
('alt-q-direito-constitucional-controle-constitucionalidade-001-B', 'q-direito-constitucional-controle-constitucionalidade-001', 'B', 'Presidente da República.', false, 2, 'Incorreto. É legitimado universal (art. 103, I, CF).'),
('alt-q-direito-constitucional-controle-constitucionalidade-001-C', 'q-direito-constitucional-controle-constitucionalidade-001', 'C', 'Mesa do Senado Federal.', false, 3, 'Incorreto. É legitimado universal (art. 103, II, CF).'),
('alt-q-direito-constitucional-controle-constitucionalidade-001-D', 'q-direito-constitucional-controle-constitucionalidade-001', 'D', 'Procurador-Geral da República.', false, 4, 'Incorreto. É legitimado universal (art. 103, VI, CF).'),
('alt-q-direito-constitucional-controle-constitucionalidade-001-E', 'q-direito-constitucional-controle-constitucionalidade-001', 'E', 'Conselho Federal da Ordem dos Advogados do Brasil.', false, 5, 'Incorreto. É legitimado universal (art. 103, VII, CF).'),
('alt-q-direito-constitucional-seguranca-publica-001-A', 'q-direito-constitucional-seguranca-publica-001', 'A', 'Polícia Federal.', true, 1, 'Correto. Atribuição expressa da Polícia Federal (art. 144, § 1º, I, CF).'),
('alt-q-direito-constitucional-seguranca-publica-001-B', 'q-direito-constitucional-seguranca-publica-001', 'B', 'Polícia Rodoviária Federal.', false, 2, 'Incorreto. Destina-se ao patrulhamento ostensivo das rodovias federais.'),
('alt-q-direito-constitucional-seguranca-publica-001-C', 'q-direito-constitucional-seguranca-publica-001', 'C', 'Polícia Civil dos Estados.', false, 3, 'Incorreto. Possui competência residual para infrações penais estaduais (ressalvada a militar e federal).'),
('alt-q-direito-constitucional-seguranca-publica-001-D', 'q-direito-constitucional-seguranca-publica-001', 'D', 'Guarda Municipal Metropolitana.', false, 4, 'Incorreto. Destina-se à proteção de bens, serviços e instalações municipais.'),
('alt-q-direito-constitucional-seguranca-publica-001-E', 'q-direito-constitucional-seguranca-publica-001', 'E', 'Polícia Ferroviária Federal.', false, 5, 'Incorreto. Destina-se ao patrulhamento ostensivo das ferrovias federais.'),
('alt-q-portugues-sintaxe-032-A', 'q-portugues-sintaxe-032', 'A', 'A administração pública pode afastar as normas de Sintaxe do Período e Orações por mera conveniência subjetiva do gestor sem amparo em lei.', false, 1, 'Incorreto. A assertiva contraria as disposições normativas e jurisprudenciais do tema.'),
('alt-q-portugues-sintaxe-032-B', 'q-portugues-sintaxe-032', 'B', 'A inobservância dos preceitos essenciais de Sintaxe do Período e Orações não gera qualquer nulidade ou responsabilidade jurídica.', false, 2, 'Incorreto. A assertiva contraria as disposições normativas e jurisprudenciais do tema.'),
('alt-q-portugues-sintaxe-032-C', 'q-portugues-sintaxe-032', 'C', 'Os atos decorrentes de Sintaxe do Período e Orações prescindem de publicidade, motivação ou submissão a órgãos de controle.', false, 3, 'Incorreto. A assertiva contraria as disposições normativas e jurisprudenciais do tema.'),
('alt-q-portugues-sintaxe-032-D', 'q-portugues-sintaxe-032', 'D', 'A observância rigorosa aos princípios e regras legais de Sintaxe do Período e Orações assegura a validade dos atos, a eficácia do serviço público e a conformidade com as normas constitucionais.', true, 4, 'Gabarito Oficial. A matéria de Sintaxe do Período e Orações subordina-se à legalidade, à jurisprudência pacificada e à teoria geral do direito aplicada aos concursos públicos.'),
('alt-q-portugues-sintaxe-032-E', 'q-portugues-sintaxe-032', 'E', 'A legislação brasileira revogou integralmente as exigências formais relativas a Sintaxe do Período e Orações desde o ano de 2018.', false, 5, 'Incorreto. A assertiva contraria as disposições normativas e jurisprudenciais do tema.'),
